CREATE TABLE IF NOT EXISTS sessions (session_id TEXT PRIMARY KEY, agent_id TEXT NOT NULL, user_id TEXT, metadata TEXT, session_state TEXT, summary TEXT, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_agent_id ON sessions(agent_id);
CREATE TABLE IF NOT EXISTS runs (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, agent_id TEXT, user_id TEXT, input TEXT, content TEXT, tool_calls TEXT, status TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(session_id) REFERENCES sessions(session_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_runs_session_id ON runs(session_id);
CREATE TABLE IF NOT EXISTS run_messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(run_id) REFERENCES runs(run_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_run_messages_run_id ON run_messages(run_id);
CREATE TABLE IF NOT EXISTS memories (memory_id TEXT PRIMARY KEY, memory TEXT NOT NULL, topics TEXT, user_id TEXT, agent_id TEXT, team_id TEXT, input TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_memories_user_agent ON memories(user_id, agent_id);
CREATE TABLE IF NOT EXISTS team_sessions (session_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, user_id TEXT, members TEXT, metadata TEXT, session_state TEXT, summary TEXT, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_team_sessions_team_id ON team_sessions(team_id);
CREATE TABLE IF NOT EXISTS team_runs (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, team_id TEXT, user_id TEXT, input TEXT, content TEXT, tool_calls TEXT, status TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(session_id) REFERENCES team_sessions(session_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_team_runs_session_id ON team_runs(session_id);
CREATE TABLE IF NOT EXISTS team_run_messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(run_id) REFERENCES team_runs(run_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_team_run_messages_run_id ON team_run_messages(run_id);
CREATE TABLE IF NOT EXISTS workflow_sessions (session_id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, user_id TEXT, metadata TEXT, session_state TEXT, summary TEXT, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_workflow_sessions_workflow_id ON workflow_sessions(workflow_id);
CREATE TABLE IF NOT EXISTS workflow_runs (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, workflow_id TEXT, user_id TEXT, input TEXT, content TEXT, tool_calls TEXT, status TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(session_id) REFERENCES workflow_sessions(session_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_workflow_runs_session_id ON workflow_runs(session_id);
CREATE TABLE IF NOT EXISTS workflow_run_messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(run_id) REFERENCES workflow_runs(run_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_workflow_run_messages_run_id ON workflow_run_messages(run_id);
